style.css:
/* Panther Magister achtergrond */
body {
    background-image: url("https://example.com/panther-background.png"); /* Hier de URL van je afbeelding */
    background-size: cover; /* Zorgt dat de achtergrond het hele scherm vult */
    background-position: center; /* Centert de afbeelding */
    background-repeat: no-repeat; /* Voorkomt herhaling van de afbeelding */
    background-attachment: fixed; /* Houdt de achtergrond vast bij scrollen */
}
